## 2️⃣ Secure‑by‑default Boilerplate

```js
// ---------------------------------------------------
// app.js – Hardened Express starter
// ---------------------------------------------------
require('dotenv').config();               // Load .env (port, node env, etc.)
const express = require('express');
const helmet = require('helmet');         // Security headers
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');         // HTTP request logging
const cors = require('cors');             // If you need CORS
const xss = require('xss-clean');         // Basic XSS sanitisation
const mongoSanitize = require('express-mongo-sanitize');
const { body, param, query, validationResult } = require('express-validator');

const app = express();

// ---------------------------------------------------
// 1️⃣ Global Middleware
// ---------------------------------------------------

// Trust reverse proxies (e.g., when running behind Nginx/heroku)
app.set('trust proxy', 1);

// Security HTTP headers
app.use(helmet());

// CORS – adjust origin as needed
app.use(cors({
  origin: process.env.CORS_ORIGIN || '*',
  methods: ['GET','POST','PUT','DELETE','OPTIONS'],
  credentials: true,
}));

// Body parsers – limit size to avoid DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Data sanitisation
app.use(xss());
app.use(mongoSanitize());

// HTTP request logger (dev vs production)
if (process.env.NODE_ENV === 'production') {
  app.use(morgan('combined'));
} else {
  app.use(morgan('dev'));
}

// ---------------------------------------------------
// 2️⃣ Rate limiting (basic DoS protection)
// ---------------------------------------------------
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                 // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
  message: {
    status: 429,
    error: 'Too many requests, please try again later.',
  },
});
app.use('/users', apiLimiter);      // apply to any route that may be hit frequently
// (or app.use(apiLimiter) for global protection)

// ---------------------------------------------------
// 3️⃣ Centralised error handling helpers
// ---------------------------------------------------
class ApiError extends Error {
  constructor(statusCode, message, isOperational = true) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = isOperational;
    Error.captureStackTrace(this, this.constructor);
  }
}

// Wrap async route handlers to forward errors to next()
const asyncHandler = fn => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ---------------------------------------------------
// 4️⃣ Routes (with validation & sanitisation)
// ---------------------------------------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Supports optional pagination via query string:
 *   ?page=1&limit=20
 */
app.get(
  '/users',
  // ---- Validation chain ----
  [
    query('page')
      .optional()
      .isInt({ min: 1 })
      .toInt()
      .withMessage('page must be a positive integer'),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .toInt()
      .withMessage('limit must be an integer between 1‑100'),
  ],
  asyncHandler(async (req, res, next) => {
    // ---- Input validation result ----
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      // Bad request – never expose raw validator array in production
      return next(new ApiError(400, errors.array().map(e => e.msg).join(', ')));
    }

    // Simulate fetching from DB or other source
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com' },
    ];

    // Basic pagination (optional)
    const page = req.query.page || 1;
    const limit = req.query.limit || users.length;
    const start = (page - 1) * limit;
    const paged = users.slice(start, start + limit);

    res.json(paged);
  })
);

// ---------------------------------------------------
// 5️⃣ 404 handler (must be after all routes)
// ---------------------------------------------------
app.use((req, res, next) => {
  next(new ApiError(404, `Cannot ${req.method} ${req.originalUrl}`));
});

// ---------------------------------------------------
// 6️⃣ Central error middleware
// ---------------------------------------------------
app.use((err, req, res, next) => {
  // If the error is not an instance of ApiError, wrap it
  if (!(err instanceof ApiError)) {
    console.error('⚠️ Unexpected error:', err);
    err = new ApiError(500, 'Internal Server Error', false);
  }

  // Do not leak stack traces in production
  const response = {
    status: err.statusCode,
    error: err.message,
  };
  if (process.env.NODE_ENV !== 'production') {
    response.stack = err.stack;
  }

  res.status(err.statusCode).json(response);
});

// ---------------------------------------------------
// 7️⃣ Graceful shutdown (handle SIGTERM / SIGINT)
// ---------------------------------------------------
function shutdown(signal) {
  console.log(`🛑 Received ${signal}. Shutting down gracefully…`);
  server.close(() => {
    console.log('🔌 Server closed. Exiting process.');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('✖️ Force shutdown.');
    process.exit(1);
  }, 10_000);
}
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

// ---------------------------------------------------
// 8️⃣ Server start (port from env, fallback to 3000)
// ---------------------------------------------------
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`🚀 Server running on port ${PORT}`);
});

module.exports = app;   // keep for testing
```

### What changed and why?

| # | Change | Security / Stability Benefit |
|---|--------|------------------------------|
| **Helmet** | Sets a curated set of HTTP security headers (CSP, X‑Frame‑Options, HSTS, etc.). | Mitigates click‑jacking, MIME sniffing, XSS, and forces HTTPS. |
| **Rate‑limit** | Limits the number of requests per IP. | Thwarts brute‑force and simple DoS attacks. |
| **Body size limits** (`express.json({ limit: '10kb' })`) | Prevents attackers from sending massive payloads to exhaust memory. |
| **XSS & Mongo sanitisation** (`xss-clean`, `express-mongo-sanitize`) | Strips dangerous characters (`$`, `.`) and HTML tags. | Reduces injection vectors, especially if you later add a DB. |
| **CORS** | Explicitly defines allowed origins. | Prevents other sites from silently calling your API. |
| **`express-validator`** | Declarative validation for query / body / params. | Guarantees type safety and whitelists accepted data. |
| **Async wrapper** (`asyncHandler`) | Guarantees that any rejected promise is passed to the central error handler. | Avoids “unhandled promise rejection” crashes. |
| **Custom `ApiError` class** | Uniform structure for operational errors. | Simplifies downstream error handling and prevents leaking stack traces. |
| **404 handler** | Returns a proper *Not Found* JSON object. | Removes ambiguous “hang” for unknown routes. |
| **Central error middleware** | Logs unexpected errors, hides internal details in production. | Prevents information leakage while still providing useful info in dev. |
| **Graceful shutdown** (`SIGTERM`, `SIGINT`) | Allows pending connections to finish before exit. | Prevents abrupt termination that could corrupt in‑flight writes (e.g., DB). |
| **Environment‑driven config** | `process.env.PORT`, `process.env.NODE_ENV`, `process.env.CORS_ORIGIN`. | Allows the same code to run safely across dev / staging / prod. |
| **Morgan logging** | Structured request logs (combined format) when in production. | Gives visibility for audit / intrusion detection. |

---

## 3️⃣ Additional Recommendations (beyond the file)

| Area | Action |
|------|--------|
| **Dependency Updates** | Run `npm audit` and `npm outdated` regularly. Consider `npm install helmet@^7` etc. |
| **Static Analysis** | Add ESLint with the `security` plugin (`eslint-plugin-security`). |
| **Testing** | Include unit tests for input validation (`supertest`). |
| **Secrets Management** | Store any future secrets (DB passwords, JWT secrets) in a vault or at least a `.env` file that is **git‑ignored**. |
| **HTTPS** | Deploy behind a TLS terminator (NGINX, Load Balancer) and enable `helmet.hsts`. |
| **Content Security Policy** | Fine‑tune CSP via `helmet.contentSecurityPolicy` for any front‑end you might serve. |
| **Health Checks** | Extend `/health` to also report DB connectivity, queue health, etc. |
| **Metrics** | Export Prometheus metrics (`express-prometheus-middleware`) for observability. |
| **Dependency Injection / Controllers** | As the app grows, separate route definitions into dedicated routers (`routes/users.js`) and keep business logic in services. This reduces the attack surface of the main file and improves testability. |

---

## 4️⃣ Quick “drop‑in” checklist

1. `npm i helmet express-rate-limit morgan cors xss-clean express-mongo-sanitize express-validator dotenv`  
2. Add a `.env` file (and `.gitignore` it) with at least `PORT=3000` and `NODE_ENV=production` for prod.  
3. Replace the current `app.js` content with the hardened version above.  
4. Run `npm run lint && npm test` (or whichever scripts you have) to verify nothing broke.  
5. Deploy behind a reverse‑proxy that terminates TLS and forwards to the Node process.

---

### TL;DR

* **Add security header middleware (`helmet`).**  
* **Implement rate limiting & request‑size caps.**  
* **Validate every external input (query, params, body) using `express-validator` (or a schema lib like `joi`).**  
* **Centralise error handling with a custom `ApiError` class and an async wrapper.**  
* **Log requests & unexpected errors, hide stack traces in production.**  
* **Gracefully handle termination signals.**  
* **Make the port/configuration environment‑driven.**

By incorporating the above changes you’ll transform the toy demo into a **production‑ready, attack‑resilient API** while keeping the code clean and maintainable. Happy coding!

