## `verify-credentials.js`

```js
#!/usr/bin/env node
/* -------------------------------------------------------------
   verify-credentials.js
   Small script that validates the credentials found in .env.test
   ------------------------------------------------------------- */

require('dotenv').config({ path: '.env.test' });

const { URL } = require('url');
const { Client } = require('pg');
const fetch = require('node-fetch'); // v3+ ESM‑style, but works with CommonJS via dynamic import
const AWS = require('aws-sdk');
const Stripe = require('stripe');

async function checkPostgres(databaseUrl) {
  const client = new Client({ connectionString: databaseUrl });
  try {
    await client.connect();
    // Simple lightweight query – does not require any specific schema
    const res = await client.query('SELECT 1 AS ok');
    await client.end();
    return { ok: true, result: res.rows[0].ok };
  } catch (err) {
    return { ok: false, error: err.message };
  }
}

async function checkAnthropic(apiKey) {
  // Anthropic's "Info" endpoint: https://api.anthropic.com/v1/versions
  // It returns a JSON list of supported API versions; 200 indicates a good key.
  const url = 'https://api.anthropic.com/v1/versions';
  try {
    const resp = await fetch(url, {
      headers: { 'x-api-key': apiKey },
    });
    if (!resp.ok) {
      return { ok: false, status: resp.status, body: await resp.text() };
    }
    const data = await resp.json();
    return { ok: true, versions: data };
  } catch (err) {
    return { ok: false, error: err.message };
  }
}

async function checkStripe(secretKey) {
  const stripe = Stripe(secretKey);
  try {
    // Retrieve the account – cheap, no charge.
    const acct = await stripe.accounts.retrieve();
    return { ok: true, account: acct.id };
  } catch (err) {
    // Stripe SDK throws a structured error object
    return { ok: false, error: err.message, code: err?.code };
  }
}

async function checkAWS(accessKeyId, secretAccessKey) {
  // Use STS GetCallerIdentity – it simply returns the ARN of the caller.
  const sts = new AWS.STS({
    accessKeyId,
    secretAccessKey,
    // Force the SDK to use the US‑East‑1 endpoint (STS is global but the SDK
    // needs a region to be set). No network‑level permissions are needed beyond
    // being able to call STS.
    region: 'us-east-1',
    // Short timeout – we only need a quick check.
    httpOptions: { timeout: 5000 },
  });

  return new Promise(resolve => {
    sts.getCallerIdentity({}, (err, data) => {
      if (err) {
        resolve({ ok: false, error: err.message, code: err.code });
      } else {
        resolve({ ok: true, arn: data.Arn });
      }
    });
  });
}

async function checkLogfire(token) {
  // Logfire offers a health‑check endpoint: https://logfire.ai/api/v1/health
  // (If the real service does not have one, you can replace this with any
  // endpoint that returns 200 for a valid token.)
  const url = 'https://logfire.ai/api/v1/health';
  try {
    const resp = await fetch(url, {
      headers: { Authorization: `Bearer ${token}` },
    });
    if (!resp.ok) {
      return { ok: false, status: resp.status, body: await resp.text() };
    }
    return { ok: true };
  } catch (err) {
    return { ok: false, error: err.message };
  }
}

/* -------------------------------------------------------------
   MAIN – run all checks and print a summary.
   ------------------------------------------------------------- */
(async () => {
  const results = {};

  // ---- DATABASE_URL ------------------------------------------------
  if (process.env.DATABASE_URL) {
    console.log('🔎 Checking PostgreSQL connection …');
    results.database = await checkPostgres(process.env.DATABASE_URL);
  } else {
    results.database = { ok: false, error: 'DATABASE_URL not set' };
  }

  // ---- AWS ---------------------------------------------------------
  if (process.env.AWS_ACCESS_KEY_ID && process.env.AWS_SECRET_ACCESS_KEY) {
    console.log('🔎 Checking AWS STS credentials …');
    results.aws = await checkAWS(
      process.env.AWS_ACCESS_KEY_ID,
      process.env.AWS_SECRET_ACCESS_KEY
    );
  } else {
    results.aws = { ok: false, error: 'AWS keys missing' };
  }

  // ---- ANTHROPIC ----------------------------------------------------
  if (process.env.ANTHROPIC_API_KEY) {
    console.log('🔎 Checking Anthropic API key …');
    results.anthropic = await checkAnthropic(process.env.ANTHROPIC_API_KEY);
  } else {
    results.anthropic = { ok: false, error: 'ANTHROPIC_API_KEY missing' };
  }

  // ---- STRIPE -------------------------------------------------------
  if (process.env.STRIPE_SECRET_KEY) {
    console.log('🔎 Checking Stripe secret key …');
    results.stripe = await checkStripe(process.env.STRIPE_SECRET_KEY);
  } else {
    results.stripe = { ok: false, error: 'STRIPE_SECRET_KEY missing' };
  }

  // ---- LOGFIRE ------------------------------------------------------
  if (process.env.LOGFIRE_TOKEN) {
    console.log('🔎 Checking Logfire token …');
    results.logfire = await checkLogfire(process.env.LOGFIRE_TOKEN);
  } else {
    results.logfire = { ok: false, error: 'LOGFIRE_TOKEN missing' };
  }

  // -------------------------------------------------------------
  console.log('\n=== CREDENTIAL VERIFICATION SUMMARY ===');
  console.log(JSON.stringify(results, null, 2));

  // Exit code 0 if all are ok, otherwise 1
  const allGood = Object.values(results).every(r => r.ok);
  process.exit(allGood ? 0 : 1);
})();
```

### How to run it

1. **Install the tiny set of dependencies** needed for the checks:

   ```bash
   npm install pg node-fetch@2 aws-sdk stripe dotenv
   ```

   > *Why `node-fetch@2`?* It still exports a CommonJS function, which works nicely when the script itself is executed via `node`. (If you’re using ESM you can remove the version pin and use the built‑in `fetch` in Node ≥18.)

2. **Make the script executable** (optional):

   ```bash
   chmod +x verify-credentials.js
   ```

3. **Run the script** from the root of the repository (it will automatically load `.env.test`):

   ```bash
   node verify-credentials.js
   ```

   You should see a series of “checking …” lines followed by a JSON snapshot similar to:

   ```json
   {
     "database": { "ok": true, "result": 1 },
     "aws": { "ok": true, "arn": "arn:aws:sts::123456789012:assumed-role/..." },
     "anthropic": { "ok": true, "versions": ["2023-06-01", "2023-09-01"] },
     "stripe": { "ok": true, "account": "acct_1A2b3C4d5E6F" },
     "logfire": { "ok": true }
   }
   ```

   If any credential fails, the corresponding entry will contain an `error` field and the process will exit with a non‑zero code, allowing you to hook it into CI pipelines (`npm test`, GitHub Actions, etc.).

### What each check actually does

| Credential | Endpoint / Call | Reason it proves “validity” |
|------------|-----------------|-----------------------------|
| `DATABASE_URL` | `SELECT 1` against the DB | Guarantees the network can reach the host, the DB accepts the connection string, and the user has at least basic query rights. |
| `AWS_ACCESS_KEY_ID` / `AWS_SECRET_ACCESS_KEY` | `STS GetCallerIdentity` | STS always succeeds for *any* set of IAM credentials that can be authenticated – it returns the caller’s ARN, proving the key pair is accepted. |
| `ANTHROPIC_API_KEY` | `GET https://api.anthropic.com/v1/versions` (header `x-api-key`) | A 200 response means the API key is recognized; the endpoint is cheap and does not consume request quota. |
| `STRIPE_SECRET_KEY` | `stripe.accounts.retrieve()` | Stripe will return the account object if the secret key is correct; otherwise it throws an authentication error. |
| `LOGFIRE_TOKEN` | (example) `GET https://logfire.ai/api/v1/health` with `Authorization: Bearer <token>` | The health endpoint replies 200 only for a token that the service recognises. If Logfire uses a different endpoint you can swap the URL. |

### Handling the “stale” case

If any of the checks return **false** (`ok: false`), you’ll see the exact error message (e.g., `password authentication failed`, `Invalid access key id`, `401 Unauthorized`). Those messages let you decide whether:

* The credential was **revoked** or **rotated** – generate a fresh one.
