const userSchema = Joi.object({
  name:  Joi.string().trim().min(1).max(100).required(),
  email: Joi.string().email({ tlds: { allow: false } }).required(),
});

app.post('/users', async (req, res, next) => {
  try {
    const { error, value } = userSchema.validate(req.body, { abortEarly: false });
    if (error) {
      const err = new Error('Validation failed');
      err.statusCode = 422;
      err.details = error.details.map(d => d.message);
      throw err;
    }

    // TODO: persist user (e.g., DB insert)
    res.status(201).json({ id: /* generated id */, ...value });
  } catch (e) {
    next(e);
  }
});
```

> **Why:** Prevents injection attacks (e.g., NoSQL/SQL injection) and ensures the API only receives data that conforms to your contract.

---

## 5. Parse and limit request bodies

If you later accept JSON payloads, limit the size to avoid memory‑exhaustion attacks.

```js
app.use(express.json({ limit: '10kb' }));   // adjust size as appropriate
app.use(express.urlencoded({ extended: false, limit: '5kb' }));
```

---

## 6. Avoid hard‑coded configuration

Move the port (and any secret values) to environment variables. Provide a sensible default for local development.

```js
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

You can also validate that required env vars are present at startup:

```js
if (!process.env.NODE_ENV) {
  console.warn('NODE_ENV not set – defaulting to "development"');
}
```

---

## 7. Graceful shutdown & uncaught‑exception handling

```js
process.on('unhandledRejection', (reason) => {
  console.error('Unhandled Promise Rejection:', reason);
  // optional: clean up resources, then exit
});

process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1); // exit – the process is in an unknown state
});

process.on('SIGTERM', () => {
  console.log('SIGTERM received – closing server...');
  server.close(() => process.exit(0));
});
```

> **Why:** Guarantees that the process does not stay alive in a corrupted state.

---

## 8. Add a **Content‑Security‑Policy** (CSP) via Helmet

If you ever serve HTML, a CSP mitigates XSS:

```js
app.use(
