#!/usr/bin/env node
/**
 * Verify that the environment‑variables defined in .env.test (or process.env)
 * point to live services.
 *
 * This script is deliberately defensive:
 *   • It logs **only** success/failure – never prints the secret itself.
 *   • It uses short time‑outs (5 s) so a bad credential doesn’t block CI.
 *   • Errors are caught and reported with a concise message.
 *
 * To run:
 *   $ npm install pg aws-sdk @anthropic-ai/sdk stripe node-fetch
 *   $ node scripts/verify-creds.js
 */

require('dotenv').config({ path: '.env.test' });

const { Client } = require('pg');
const AWS = require('aws-sdk');
const { Anthropic } = require('@anthropic-ai/sdk');
const Stripe = require('stripe');
const fetch = require('node-fetch');

const TIMEOUT_MS = 5000;

// Helper – wrap a promise with a timeout
const withTimeout = (promise, ms, name) =>
  Promise.race([
    promise,
    new Promise((_, reject) =>
      setTimeout(() => reject(new Error(`${name} timed out after ${ms} ms`)), ms)
    ),
  ]);

// ---------- 1. DATABASE ----------
async function checkDatabase() {
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error('DATABASE_URL not set');

  const client = new Client({ connectionString: url });
  await withTimeout(client.connect(), TIMEOUT_MS, 'Postgres connect');
  const res = await withTimeout(client.query('SELECT 1'), TIMEOUT_MS, 'Postgres query');
  await client.end();
  if (res?.rowCount !== 1) throw new Error('Unexpected DB response');
  console.log('✅ DATABASE_URL works');
}

// ---------- 2. AWS ----------
async function checkAWS() {
  const { AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY } = process.env;
  if (!AWS_ACCESS_KEY_ID || !AWS_SECRET_ACCESS_KEY)
    throw new Error('AWS credentials missing');

  const sts = new AWS.STS({
    accessKeyId: AWS_ACCESS_KEY_ID,
    secretAccessKey: AWS_SECRET_ACCESS_KEY,
    region: 'us-east-1',
    httpOptions: { timeout: TIMEOUT_MS },
  });

  const data = await withTimeout(
    sts.getCallerIdentity().promise(),
    TIMEOUT_MS,
    'AWS STS'
  );
  if (!data?.Account) throw new Error('AWS returned no account ID');
  console.log('✅ AWS credentials are valid');
}

// ---------- 3. Anthropic ----------
async function checkAnthropic() {
  const key = process.env.ANTHROPIC_API_KEY;
  if (!key) throw new Error('ANTHROPIC_API_KEY not set');

  const client = new Anthropic({ apiKey: key, timeout: TIMEOUT_MS });
  // Minimal request – 1‑token message, no streaming
  const resp = await withTimeout(
    client.messages.create({
      model: 'claude-2.0', // any model that exists for the account
      max_tokens: 1,
      messages: [{ role: 'user', content: 'ping' }],
    }),
    TIMEOUT_MS,
    'Anthropic API'
  );
  // If we got a response object, the key is good
  console.log('✅ ANTHROPIC_API_KEY works');
}

// ---------- 4. Stripe ----------
async function checkStripe() {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) throw new Error('STRIPE_SECRET_KEY not set');

  const stripe = Stripe(key, { apiVersion: '2023-10-16', timeout: TIMEOUT_MS });
  const charges = await withTimeout(stripe.charges.list({ limit: 1 }), TIMEOUT_MS, 'Stripe API');
  if (!Array.isArray(charges?.data)) throw new Error('Unexpected Stripe response');
  console.log('✅ STRIPE_SECRET_KEY works');
}

// ---------- 5. Logfire (example) ----------
async function checkLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) throw new Error('LOGFIRE_TOKEN not set');

  // Replace with the actual health endpoint your Logfire instance provides.
  // Here we just demonstrate a generic GET request.
  const url = `https://logfire.io/api/v1/health?token=${encodeURIComponent(token)}`;
  const resp = await withTimeout(fetch(url, { timeout: TIMEOUT_MS }), TIMEOUT_MS, 'Logfire');
  if (!resp.ok) throw new Error(`Logfire responded ${resp.status}`);
  console.log('✅ LOGFIRE_TOKEN works (health endpoint reachable)');
}

// ---------- Run all checks ----------
(async () => {
  const checks = [
    { name: 'DATABASE_URL', fn: checkDatabase },
    { name: 'AWS credentials', fn: checkAWS },
    { name: 'ANTHROPIC_API_KEY', fn: checkAnthropic },
    { name: 'STRIPE_SECRET_KEY', fn: checkStripe },
    { name: 'LOGFIRE_TOKEN', fn: checkLogfire },
  ];

  for (const { name, fn } of checks) {
    try {
      await fn();
    } catch (err) {
      // **Do NOT print the secret** – only the identifier and error message.
      console.error(`❌ ${name} verification failed: ${err.message}`);
    }
  }
})();
