const { Logfire } = require('logfire'); // Logfire's JS client, if installed

// Helper for pretty output
const ok = (msg) => console.log(`✅ ${msg}`);
const fail = (msg, err) => console.error(`❌ ${msg}\n   → ${err?.message || err}`);

(async () => {
  // ---------------------------------------------------------
  // 1️⃣ PostgreSQL (DATABASE_URL)
  // ---------------------------------------------------------
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    console.warn('⚠️  DATABASE_URL not set – skipping DB check');
  } else {
    const client = new Client({ connectionString: dbUrl });
    try {
      await client.connect();
      const res = await client.query('SELECT 1 AS ok');
      if (res.rows[0]?.ok === 1) ok('PostgreSQL connection succeeded');
      else throw new Error('Unexpected DB response');
    } catch (e) {
      fail('PostgreSQL connection failed', e);
    } finally {
      await client.end().catch(() => {});
    }
  }

