    console.warn('⚠️  AWS credentials not set – skipping AWS check');
  } else {
    const sts = new AWS.STS({ apiVersion: '2011-06-15' });
    try {
      const data = await sts.getCallerIdentity().promise();
      ok(`AWS STS call succeeded – ARN: ${data.Arn}`);
    } catch (e) {
      fail('AWS STS call failed', e);
    }
  }

  // ---------------------------------------------------------
  // 3️⃣ Anthropic (ANTHROPIC_API_KEY)
  // ---------------------------------------------------------
  const anthropicKey = process.env.ANTHROPIC_API_KEY;
  if (!anthropicKey) {
    console.warn('⚠️  ANTHROPIC_API_KEY not set – skipping Anthropic check');
  } else {
    const client = new Anthropic({ apiKey: anthropicKey });
    try {
      // The `/v1/models` endpoint is cheap and read‑only.
      const models = await client.models.list();
      ok(`Anthropic API responded – ${models.length} model(s) available`);
    } catch (e) {
      fail('Anthropic API call failed', e);
    }
  }

  // ---------------------------------------------------------
  // 4️⃣ Stripe (STRIPE_SECRET_KEY)
  // ---------------------------------------------------------
  const stripeKey = process.env.STRIPE_SECRET_KEY;
  if (!stripeKey) {
    console.warn('⚠️  STRIPE_SECRET_KEY not set – skipping Stripe check');
  } else {
    const stripe = Stripe(stripeKey, { apiVersion: '2023-10-16' });
    try {
      // Retrieve the account object – no money moves.
      const acct = await stripe.accounts.retrieve();
      ok(`Stripe account retrieved – ID: ${acct.id}`);
    } catch (e) {
      fail('Stripe API call failed', e);
    }
  }

  // ---------------------------------------------------------
  // 5️⃣ Logfire (LOGFIRE_TOKEN) – simple ping
  // ---------------------------------------------------------
  const logfireToken = process.env.LOGFIRE_TOKEN;
  if (!logfireToken) {
