// ---------------------------------------------------------------
async function checkLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) {
    log('LOGFIRE_TOKEN missing in .env.test', 'WARN');
    return false;
  }

  // Logfire (by Logflare) exposes a simple “ping” endpoint:
  const url = `https://api.logflare.app/api/v1/ping`;
  try {
    const res = await fetch(url, {
      headers: { Authorization: `Bearer ${token}` },
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json();
    if (data.ok) {
      log('✅ Logfire token appears valid');
      return true;
    }
    throw new Error('Unexpected response payload');
  } catch (err) {
    log(`❌ Logfire token check failed: ${err.message}`, 'ERROR');
    return false;
  }
}

