// Main orchestration
// ---------------------------------------------------------------
(async () => {
  log('Starting credential validation...');

  const results = await Promise.allSettled([
    checkDatabase(),
    checkAws(),
    checkAnthropic(),
    checkStripe(),
    checkLogfire(),
  ]);

  const summary = results.map((r, i) => ({
    name: ['PostgreSQL', 'AWS', 'Anthropic', 'Stripe', 'Logfire'][i],
    success: r.status === 'fulfilled' ? r.value : false,
  }));

