// app.js
// ------------------------------------------------------------
// Secure, validated, and error‑aware Express starter.
// ------------------------------------------------------------

require('dotenv').config();           // Load .env (never commit real secrets!)
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');      // Structured request logging
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// ---------- 1️⃣ Global middleware ----------
app.use(helmet());                    // Secure HTTP headers
app.use(
  cors({
    origin: process.env.ALLOWED_ORIGINS?.split(',') ?? [], // e.g. "https://myapp.com"
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    credentials: true,
  })
);
app.use(express.json({ limit: '10kb' })); // Prevent huge bodies
app.use(
  rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100,                 // limit each IP to 100 requests per window
    standardHeaders: true,
    legacyHeaders: false,
    message: { error: 'Too many requests, try again later.' },
  })
);
app.use(morgan('combined', {
  skip: (req, res) => process.env.NODE_ENV === 'test', // silence test logs
}));

// ---------- 2️⃣ Centralised async error wrapper ----------
const asyncWrap = fn => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ---------- 3️⃣ Validation helper ----------
const handleValidation = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Do **not** echo back raw values; just enumerate fields.
    return res.status(400).json({
      error: 'Invalid request parameters',
      details: errors.array().map(err => ({
        field: err.param,
        issue: err.msg,
      })),
    });
  }
  next();
};

// ---------- 4️⃣ Routes ----------
app.get(
  '/health',
  asyncWrap(async (req, res) => {
    // Example of a tiny async action (could later be DB ping)
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  })
);

app.get(
  '/users',
  // No body, but we *could* validate query params (e.g., pagination)
  [
    query('page')
      .optional()
      .isInt({ min: 1 })
      .toInt()
      .withMessage('Page must be a positive integer'),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .toInt()
      .withMessage('Limit must be between 1 and 100'),
    handleValidation,
  ],
  asyncWrap(async (req, res) => {
    // In a real app you would fetch from DB using the validated params.
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    res.json(users);
  })
);

// ---------- 5️⃣ Global error handler ----------
app.use((err, req, res, next) => {
  // Log internally – never expose stack traces to the client in prod.
  console.error(err); // Replace with winston/pino for production.

  const status = err.status || 500;
  const response = {
    error: err.message || 'Internal Server Error',
  };

  // Optionally add a request‑ID for tracing (if you generate one earlier)
  if (process.env.NODE_ENV !== 'production') {
    response.stack = err.stack; // Helpful during dev only
  }

  res.status(status).json(response);
});

// ---------- 6️⃣ Server bootstrap (separate from export) ----------
if (require.main === module) {
  const PORT = process.env.PORT || 3000;

  const server = app.listen(PORT, () => {
    console.log(`🚀 Server listening on port ${PORT}`);
  });

  // Graceful shutdown
  const shutdown = () => {
    console.log('⚡ Shutting down...');
    server.close(() => {
      console.log('✅ Server closed');
      process.exit(0);
    });
  };
  process.on('SIGTERM', shutdown);
  process.on('SIGINT', shutdown);
  process.on('unhandledRejection', (reason) => {
    console.error('💥 Unhandled Rejection:', reason);
    shutdown();
  });
  process.on('uncaughtException', (err) => {
    console.error('💥 Uncaught Exception:', err);
    shutdown();
  });
}

// Export for testing
module.exports = app;
```

