// verify-creds.js
// -------------------------------------------------
// Run with:  node verify-creds.js
// -------------------------------------------------
require('dotenv').config();        // reads .env or .env.test automatically

const { Client } = require('pg');
const AWS = require('aws-sdk');
const fetch = require('node-fetch'); // npm i node-fetch@2 (CommonJS)
const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY);
const LOGFIRE_TOKEN = process.env.LOGFIRE_TOKEN;

// Helper to print a colored status
const green = (s) => `\x1b[32m${s}\x1b[0m`;
const red   = (s) => `\x1b[31m${s}\x1b[0m`;

async function testDatabase() {
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error('DATABASE_URL not set');

  const client = new Client({ connectionString: url, statement_timeout: 5000 });
  await client.connect();
  const res = await client.query('SELECT 1 AS ok');
  await client.end();
  return res.rows[0].ok === 1;
}

async function testAWS() {
  const { AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY } = process.env;
  if (!AWS_ACCESS_KEY_ID || !AWS_SECRET_ACCESS_KEY) throw new Error('AWS keys missing');

  const sts = new AWS.STS({
    accessKeyId: AWS_ACCESS_KEY_ID,
    secretAccessKey: AWS_SECRET_ACCESS_KEY,
    region: 'us-east-1', // region doesn't matter for STS
    httpOptions: { timeout: 5000 },
  });

  const data = await sts.getCallerIdentity().promise();
  return Boolean(data?.Account);
}

async function testAnthropic() {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) throw new Error('ANTHROPIC_API_KEY not set');

  const response = await fetch('https://api.anthropic.com/v1/messages', {
    method: 'POST',
    headers: {
      'x-api-key': apiKey,
      'content-type': 'application/json',
      'anthropic-version': '2023-06-01',
    },
    body: JSON.stringify({
      model: 'claude-3-haiku-20240307',
      max_tokens: 1,
      messages: [{ role: 'user', content: 'ping' }],
    }),
    timeout: 5000,
  });

  if (!response.ok) {
    const txt = await response.text();
    throw new Error(`Anthropic: ${response.status} – ${txt}`);
  }
  const json = await response.json();
  return Boolean(json?.id);
}

async function testStripe() {
  // Stripe library already initialised above with the secret key.
  // A simple read‑only call:
  const customers = await stripe.customers.list({ limit: 1 });
  return Array.isArray(customers?.data);
}

async function testLogfire() {
  if (!LOGFIRE_TOKEN) throw new Error('LOGFIRE_TOKEN not set');

  const resp = await fetch('https://api.logfire.io/v1/ping', {
    method: 'GET',
    headers: { Authorization: `Bearer ${LOGFIRE_TOKEN}` },
    timeout: 5000,
  });

  if (!resp.ok) {
    const txt = await resp.text();
    throw new Error(`Logfire: ${resp.status} – ${txt}`);
  }
  const body = await resp.json();
  return body?.ok === true || body?.status === 'ok';
}

// -------------------------------------------------
(async () => {
  const results = [
    { name: 'PostgreSQL', fn: testDatabase },
    { name: 'AWS STS',   fn: testAWS },
    { name: 'Anthropic',fn: testAnthropic },
    { name: 'Stripe',    fn: testStripe },
    { name: 'Logfire',   fn: testLogfire },
  ];

  console.log('\n=== Credential verification report ===\n');

  for (const { name, fn } of results) {
    try {
      const ok = await fn();
      console.log(`${name}: ${green('OK')}`);
    } catch (e) {
      console.log(`${name}: ${red('FAIL')} – ${e.message}`);
    }
  }

  console.log('\n--- Done ---\n');
})();
```

