// app.js – Secure Express starter
// ---------------------------------------------------
require('dotenv').config();          // Load .env (never commit secrets)
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const Joi = require('joi');
const pino = require('pino')();      // Structured logger

const app = express();

// ---------- Middleware stack ----------
app.use(helmet());                     // Secure HTTP headers
app.use(cors({ origin: ['https://my-frontend.com'] })); // Adjust origin as needed
app.use(express.json({ limit: '100kb' })); // Body size limit
app.use((req, res, next) => {
  pino.info({ method: req.method, url: req.originalUrl, ip: req.ip });
  next();
});

// Simple rate‑limiting for all routes (adjust windows/limits as required)
app.use(rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
}));

// ---------- Validation schemas ----------
const usersQuerySchema = Joi.object({
  limit: Joi.number().integer().min(1).max(100).default(20),
  offset: Joi.number().integer().min(0).default(0),
});

function validateUsersQuery(req, res, next) {
  const { error, value } = usersQuerySchema.validate(req.query);
  if (error) {
    const err = new Error(error.details[0].message);
    err.statusCode = 400;
    return next(err);
  }
  req.query = value; // sanitized values
  next();
}

// ---------- Routes ----------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', validateUsersQuery, (req, res, next) => {
  try {
    const { limit, offset } = req.query;
    // Dummy data – replace with a DB call in production
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    const users = allUsers.slice(offset, offset + limit);
    res.json(users);
  } catch (e) {
    next(e);
  }
});

// ---------- Global error handler ----------
function errorHandler(err, req, res, next) { // eslint-disable-line no-unused-vars
  const status = err.statusCode || 500;
  // Log for admins/devs
  pino.error({ err, path: req.path, method: req.method, ip: req.ip });
  // Mask internal details for 5xx errors
  const message = status === 500 ? 'Internal Server Error' : err.message;
  res.status(status).json({ error: { message } });
}
app.use(errorHandler);

// ---------- Server bootstrap ----------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

**What changed?**

* Added **Helmet**, **CORS**, **rate limiting**, and body‑size limits.  
* Switched to a **structured logger** (`pino`).  
