async function checkDatabase() {
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) return logResult('DATABASE_URL', false, 'not set');

  const client = new Client({ connectionString: dbUrl, connectionTimeoutMillis: 3000 });
  try {
    await client.connect();
    // Run a harmless query – just ask the server version
    const res = await client.query('SELECT version();');
    logResult('DATABASE_URL', true, `Server = ${res.rows[0].version}`);
  } catch (e) {
    logResult('DATABASE_URL', false, e.message);
  } finally {
