  name: Joi.string().trim().min(2).max(50).required(),
  email: Joi.string().email({ tlds: { allow: false } }).required(),
});

// Middleware
function validateCreateUser(req, res, next) {
  const { error, value } = createUserSchema.validate(req.body, { abortEarly: false });
  if (error) {
    // 400 Bad Request with details (hide specific internal rules in prod if you wish)
    return res.status(400).json({ error: 'Invalid request payload', details: error.details });
  }
  req.body = value; // use the sanitized value downstream
  next();
}

// Example route
