// ---------- 2️⃣ Rate limiting (adjust per route) ----------
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 min
  max: 100,                // 100 requests per IP
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/users', apiLimiter); // only /users is throttled in this sample

