/**
 * Simple credential‑validation script.
 *
 * • Checks that DATABASE_URL can be parsed and a DB connection can be opened.
 * • Calls a lightweight endpoint for each third‑party service to see if the key works.
 *
 * All secrets are **read from process.env**, so keep them in .env.test (or your CI env)
 * and never commit real values to source control.
 */

require('dotenv').config({ path: '.env.test' });   // load the test file
const { Client } = require('pg');
const fetch = require('node-fetch');

async function checkDatabase() {
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    console.warn('⚠️  DATABASE_URL is not set.');
    return false;
  }

  const client = new Client({ connectionString: dbUrl });
  try {
    await client.connect();
    // A minimal harmless query – just ask PostgreSQL for its version.
    const res = await client.query('SELECT version()');
    console.log('✅  Database connection OK – version:', res.rows[0].version);
    return true;
  } catch (err) {
    console.error('❌  Failed to connect to PostgreSQL:', err.message);
    return false;
  } finally {
    await client.end().catch(() => {}); // ignore close errors
  }
}

async function checkAnthropic() {
  const key = process.env.ANTHROPIC_API_KEY;
  if (!key) {
    console.warn('⚠️  ANTHROPIC_API_KEY is not set.');
    return false;
  }

  try {
    const res = await fetch('https://api.anthropic.com/v1/health', {
      headers: { 'x-api-key': key },
    });
    if (res.ok) {
      console.log('✅  Anthropic API key accepted (health endpoint).');
      return true;
    }
    console.error(`❌  Anthropic responded ${res.status}: ${await res.text()}`);
    return false;
  } catch (e) {
    console.error('❌  Error reaching Anthropic:', e.message);
    return false;
  }
}

async function checkStripe() {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) {
    console.warn('⚠️  STRIPE_SECRET_KEY is not set.');
    return false;
  }

  try {
    const res = await fetch('https://api.stripe.com/v1/ephemeral_keys', {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${key}`,
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      // No real customer ID – Stripe will reject the request, but a 401/403 tells us the key is invalid.
      body: 'customer=cus_test',
    });
    if (res.status === 401) {
      console.log('✅  Stripe key is syntactically valid (got 401 Unauthorized as expected).');
      return true;
    }
    console.error(`❌  Stripe responded ${res.status}: ${await res.text()}`);
    return false;
  } catch (e) {
    console.error('❌  Error reaching Stripe:', e.message);
    return false;
  }
}

async function checkLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) {
    console.warn('⚠️  LOGFIRE_TOKEN is not set.');
    return false;
  }

  try {
    const res = await fetch('https://api.logfire.io/v1/ping', {
      headers: { Authorization: `Bearer ${token}` },
    });
    if (res.ok) {
      console.log('✅  Logfire token accepted (ping endpoint).');
      return true;
    }
    console.error(`❌  Logfire responded ${res.status}: ${await res.text()}`);
    return false;
  } catch (e) {
    console.error('❌  Error reaching Logfire:', e.message);
    return false;
  }
}

/** ------------------------------------------------------------------ */

(async () => {
  console.log('\n--- Credential verification start ---\n');

  const results = await Promise.all([
    checkDatabase(),
    checkAnthropic(),
    checkStripe(),
    checkLogfire(),
  ]);

  const allGood = results.every(Boolean);
  console.log('\n--- Summary ---');
  console.log(`Overall status: ${allGood ? '✅  All checks passed' : '❌  Some checks failed'}`);

  // Exit with a non‑zero code if anything failed – handy for CI pipelines.
  process.exit(allGood ? 0 : 1);
})();
