// ---------- 2️⃣ Rate limiting ----------
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 min
  max: 100,                // limit each IP to 100 requests per window
  standardHeaders: true,   // Return RateLimit-* headers
  legacyHeaders: false,    // Disable X-RateLimit headers
  handler: (req, res) => {
    res.status(429).json({ error: 'Too many requests – please try again later.' });
  },
});
app.use('/users', apiLimiter); // apply to the /users endpoint (or globally)

// ---------- 3️⃣ Routes ----------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Example: a users list – **no** DB access, just static data
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

/* -------------------------------------------------
   Example of validated input (future POST route)
   ------------------------------------------------- */
const createUserSchema = Joi.object({
  name: Joi.string().trim().min(2).max(50).required(),
  email: Joi.string().email({ tlds: { allow: false } }).required(),
});

app.post('/users', async (req, res, next) => {
  try {
    // 👉 Validation – throws if invalid
    const { name, email } = await createUserSchema.validateAsync(req.body, {
      abortEarly: false, // return all errors at once
    });

    // Simulated async DB call – wrap in try/catch or rely on async error handling
    const newUser = {
      id: Date.now(),
      name,
      email,
    };
    // In real life you'd persist to DB here

    res.status(201).json(newUser);
  } catch (err) {
    // Pass validation errors (or others) to the central error handler
    next(err);
  }
});

// ---------- 4️⃣ Central error handler ----------
app.use((err, req, res, next) => {
  // Log the error with stack (structured)
  req.log.error(err);

  // Determine status code
  const status = err.isJoi ? 400 : err.status || 500;

  // Never leak internal details in production
  const response = {
    error:
      status === 500
        ? 'Internal server error'
        : err.message || 'Bad request',
    // OPTIONAL: expose validation details only for 400 responses
    ...(status === 400 && err.isJoi && { details: err.details.map(d => d.message) }),
  };

  res.status(status).json(response);
});

// ---------- 5️⃣ Server start (configurable) ----------
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  logger.info(`🚀 Server running on http://localhost:${PORT}`);
});

/* Graceful shutdown – helps when running under PM2 / Docker */
function shutdown() {
  logger.info('🛑 Received shutdown signal – closing HTTP server...');
  server.close(() => {
    logger.info('✅ HTTP server closed. Exiting process.');
    process.exit(0);
  });
  // Force quit after 10s if connections hang
  setTimeout(() => {
    logger.warn('⚠️ Forced shutdown after timeout.');
    process.exit(1);
  }, 10_000).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

module.exports = app; // keep for supertest/integration testing
```

### Why each addition matters

| Addition | Security / Reliability Benefit |
|----------|---------------------------------|
| `helmet()` | Sets 12+ security‑related HTTP headers (CSP, HSTS, X‑Frame‑Options, etc.). |
| `cors()` | Allows you to lock down which origins may call the API; wild‑card only for dev. |
| `express.json({ limit: '100kb' })` | Prevents huge payload attacks (memory exhaustion). |
| `pino` / `pino-http` | Gives you structured JSON logs (good for SIEMs, audit, and debugging). |
| `express-rate-limit` | Throttles abusive IPs – mitigates brute‑force and simple DoS. |
| Validation with **Joi** (or any schema lib) | Guarantees request bodies conform to a whitelist, preventing injection, prototype‑pollution, and type‑confusion bugs. |
| Central error‑handling middleware | Guarantees every error goes through one place, hides stack traces from callers, and logs consistently. |
| `process.env.PORT` and `.env` | Keeps secrets and environment‑specific config out of source. |
| Graceful shutdown | Allows in‑flight requests to finish and helps containers restart cleanly. |

---

## 4️⃣ Quick Checklist for Future Development

| ✅ Item | How to enforce |
|--------|----------------|
| **All incoming data** (query, body, headers) **validated** with a schema library (Joi, Zod, Yup). | Create reusable validation middleware: `app.use(validate(schema))`. |
| **Error objects** must carry a `status` property (or `isJoi`) for the central handler. | Wrap async route handlers with a utility: `asyncHandler(fn)`. |
| **Secrets** (DB passwords, API keys) loaded from environment variables **never hard‑coded**. | Use `dotenv` locally, Docker secrets/Kubernetes `Secret`s in prod. |
| **HTTPS** enforced (e.g., behind a reverse proxy). | If you run Node directly, add `app.use((req,res,next)=>{ if(!req.secure) return res.redirect('https://'+req.headers.host+req.url); next();});`. |
| **Content‑type sniffing** disabled (`X‑Content‑Type‑Options: nosniff`). | Handled by `helmet`. |
| **CSRF** protection if you ever serve HTML forms. | `csurf` middleware or same‑site cookies. |
| **Dependency health** – run `npm audit` regularly; keep packages up‑to‑date. | Add CI job that fails on vulnerabilities. |
| **Security headers** – add a CSP that fits your front‑end. | `helmet.contentSecurityPolicy({ directives: {...} })`. |
| **Rate limiting per route** – more aggressive on auth endpoints. | Create separate `apiLimiter` objects with different `max` values. |
| **Logging of audit events** (e.g., user creation). | Log at `info` level with user‑id, IP, and action. |
| **Unit / integration tests** for validation and error paths. | Use `supertest` + Jest. |

