#!/usr/bin/env node
/**
 * Quick sanity‑check script for the configuration values in .env.test
 *
 *  * Postgres connection test (pg)
 *  * AWS STS GetCallerIdentity test (aws-sdk v3)
 *  * Anthropic test – call the /v1/models endpoint (no charge)
 *  * Stripe test – retrieve the account (no charge)
 *  * Logfire test – fetch the token‑info endpoint (if any)
 *
 * The script prints a concise PASS / FAIL line for each credential.
 * Exit code:
 *   0 – all checks passed
 *   1 – at least one check failed
 *
 * ------------------------------------------------------------
 *  DO NOT run this against production “canary” values – they are
 *  intentionally invalid. Replace them with real secrets only in a
 *  safe testing environment.
 * ------------------------------------------------------------
 */

require('dotenv').config({ path: '.env.test' }); // load the test file

const { Client } = require('pg');
const { STSClient, GetCallerIdentityCommand } = require('@aws-sdk/client-sts');
const fetch = require('node-fetch'); // v3+ provides an ESM‑friendly fetch
const Stripe = require('stripe');

// Helper to format output
const green = (msg) => `\x1b[32m${msg}\x1b[0m`;
const red   = (msg) => `\x1b[31m${msg}\x1b[0m`;

(async () => {
  let allOk = true;

  // --------------------------------------------------------------
  // 1️⃣ Postgres connection
  // --------------------------------------------------------------
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    console.log(red('✖ DATABASE_URL is missing'));
    allOk = false;
  } else {
    const client = new Client({ connectionString: dbUrl });
    try {
      await client.connect();
      console.log(green('✔ DATABASE_URL – connection successful'));
    } catch (e) {
      console.log(red(`✖ DATABASE_URL – connection failed: ${e.message}`));
      allOk = false;
    } finally {
      await client.end().catch(() => {});
    }
  }

  // --------------------------------------------------------------
  // 2️⃣ AWS STS GetCallerIdentity (no cost)
  // --------------------------------------------------------------
  const { AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY } = process.env;
  if (!AWS_ACCESS_KEY_ID || !AWS_SECRET_ACCESS_KEY) {
    console.log(red('✖ AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY missing'));
    allOk = false;
  } else {
    const sts = new STSClient({
      region: 'us-east-1',
      credentials: {
        accessKeyId: AWS_ACCESS_KEY_ID,
        secretAccessKey: AWS_SECRET_ACCESS_KEY,
      },
    });
    try {
      const result = await sts.send(new GetCallerIdentityCommand({}));
      console.log(green(`✔ AWS credentials – identity ARN: ${result.Arn}`));
    } catch (e) {
      console.log(red(`✖ AWS credentials – request failed: ${e.message}`));
      allOk = false;
    }
  }

  // --------------------------------------------------------------
  // 3️⃣ Anthropic API – list models (free / rate‑limited)
  // --------------------------------------------------------------
  const ANTHROPIC_API_KEY = process.env.ANTHROPIC_API_KEY;
  if (!ANTHROPIC_API_KEY) {
    console.log(red('✖ ANTHROPIC_API_KEY missing'));
    allOk = false;
  } else {
    try {
      const response = await fetch('https://api.anthropic.com/v1/models', {
        method: 'GET',
        headers: {
          'x-api-key': ANTHROPIC_API_KEY,
          'anthropic-version': '2023-06-01',
        },
      });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const data = await response.json();
      console.log(green(`✔ Anthropic key – ${data.models?.length ?? 0} models listed`));
    } catch (e) {
      console.log(red(`✖ Anthropic key – request failed: ${e.message}`));
      allOk = false;
    }
  }

  // --------------------------------------------------------------
  // 4️⃣ Stripe secret key – retrieve account (free)
  // --------------------------------------------------------------
  const STRIPE_SECRET_KEY = process.env.STRIPE_SECRET_KEY;
  if (!STRIPE_SECRET_KEY) {
    console.log(red('✖ STRIPE_SECRET_KEY missing'));
    allOk = false;
  } else {
    const stripe = Stripe(STRIPE_SECRET_KEY, { apiVersion: '2022-11-15' });
    try {
      const acct = await stripe.accounts.retrieve();
      console.log(green(`✔ Stripe key – account id: ${acct.id}`));
    } catch (e) {
      console.log(red(`✖ Stripe key – request failed: ${e.message}`));
      allOk = false;
    }
  }

  // --------------------------------------------------------------
  // 5️⃣ Logfire token – simple health check (depends on provider)
  // --------------------------------------------------------------
  const LOGFIRE_TOKEN = process.env.LOGFIRE_TOKEN;
  if (!LOGFIRE_TOKEN) {
    console.log(red('✖ LOGFIRE_TOKEN missing'));
    allOk = false;
  } else {
    // Logfire does not expose a public “who‑am‑I”, but many services accept the token
    // via an authenticated call. We'll issue a generic GET to the base URL with the token.
    // Adjust the endpoint if Logfire provides a dedicated health endpoint.
    try {
      const response = await fetch('https://logfire-api.com/v1/health', {
        method: 'GET',
        headers: { Authorization: `Bearer ${LOGFIRE_TOKEN}` },
      });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      console.log(green('✔ LOGFIRE_TOKEN – health endpoint responded'));
    } catch (e) {
      console.log(red(`✖ LOGFIRE_TOKEN – request failed (or endpoint unavailable): ${e.message}`));
      allOk = false;
    }
  }

  // --------------------------------------------------------------
  // Final status
  // --------------------------------------------------------------
  console.log('\n=== Summary ===');
  if (allOk) {
    console.log(green('All credential checks PASSED'));
    process.exit(0);
  } else {
    console.log(red('One or more checks FAILED – see above for details'));
    process.exit(1);
  }
})();
```

