### b) Example: validate an optional `id` query param for `/users`

```js
const Joi = require('joi');

// Validation schema for /users query string
const usersQuerySchema = Joi.object({
  id: Joi.number().integer().positive(),
});

app.get('/users', asyncWrap(async (req, res) => {
  const { error, value } = usersQuerySchema.validate(req.query, { stripUnknown: true });
  if (error) {
    // Throw a friendly 400 error that will be caught by the central handler
    const err = new Error(`Invalid query parameters: ${error.message}`);
    err.statusCode = 400;
    throw err;
  }

  // If an id was supplied, filter the static list (or DB) accordingly
  const allUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com' },
  ];

  const result = value.id ? allUsers.filter(u => u.id === Number(value.id)) : allUsers;
  res.json(result);
}));
```

**What this gives you:**
* Guarantees that `id` is a positive integer.
* Strips any unexpected query parameters (`stripUnknown: true`), preventing accidental “parameter pollution”.
