  name:  Joi.string().trim().min(2).max(100).required(),
  email: Joi.string().email({ tlds: { allow: false } }).required(),
});

app.post('/users', asyncWrap(async (req, res) => {
  const { error, value } = newUserSchema.validate(req.body, { abortEarly: false });
  if (error) {
    const err = new Error(`Validation error: ${error.details.map(d => d.message).join(', ')}`);
    err.statusCode = 400;
    throw err;
  }

