  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) {
    console.error('❌ STRIPE_SECRET_KEY not set');
    return;
  }

  const stripe = Stripe(key, { apiVersion: '2023-10-16' });
  try {
    const account = await stripe.accounts.retrieve();
    console.log('✅ Stripe key valid – account ID:', account.id);
  } catch (err) {
    console.error('❌ Stripe request failed:', err.message);
  }
}

// -----------------------------------------------------------------
// 4️⃣  AWS credentials test (STS GetCallerIdentity)
// -----------------------------------------------------------------
async function testAws() {
  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;
  if (!accessKeyId || !secretAccessKey) {
    console.error('❌ AWS credentials missing');
    return;
  }

  const sts = new AWS.STS({
    accessKeyId,
    secretAccessKey,
    region: 'us-east-1', // any region works for STS
    httpOptions: { timeout: 5000 },
  });

  try {
    const data = await sts.getCallerIdentity().promise();
    console.log('✅ AWS credentials valid – ARN:', data.Arn);
  } catch (err) {
    console.error('❌ AWS STS request failed:', err.message);
  }
}

// -----------------------------------------------------------------
// 5️⃣  Logfire token test (simple GET to the health endpoint)
// -----------------------------------------------------------------
async function testLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) {
    console.error('❌ LOGFIRE_TOKEN not set');
    return;
  }

  // Logfire’s public health endpoint – replace with your actual URL if needed
  const url = 'https://api.logfire.io/health';

  try {
    const res = await fetch(url, {
      headers: { Authorization: `Bearer ${token}` },
      timeout: 5000,
    });

    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const json = await res.json();
    console.log('✅ Logfire token accepted – status:', json.status || json);
  } catch (err) {
    console.error('❌ Logfire request failed:', err.message);
  }
}

